Implement the Verilog module based on the following description.
Build a 3-bit Fibonacci LFSR (Linear Feedback Shift Register) with synchronous active high reset signal.
// (1) reset: Resets the LFSR to initial value 001.
// (2) q: The value of the LFSR.

module fibonacci_lfsr(
    input clk,
    input reset,
    output reg [2:0] q);

code:
module fibonacci_lfsr(
    input clk,
    input reset,
    output reg [2:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Set the LFSR to initial value 001
            q <= 3'b001;
        end else begin
            // Fibonacci LFSR with taps at positions 2 and 3
            q <= {q[1:0], q[2] ^ q[1]};
        end
    end

endmodule

