always@(posedge CLK)
	if(RW)
		case(DA)
		    3'b 000 : REGS[0] = D_Data;
			 3'b 001 : REGS[1] = D_Data;
			 3'b 010 : REGS[2] = D_Data;
			 3'b 011 : REGS[3] = D_Data;
			 3'b 100 : REGS[4] = D_Data;
			 3'b 101 : REGS[5] = D_Data;
			 3'b 110 : REGS[6] = D_Data;
			 3'b 111 : REGS[7] = D_Data;
