   output outp;

   reg [1:0] state;
   reg outp;

   always @( posedge clk, posedge rst )
   begin
   if( rst )
       state <= 2'b00;
   else
   begin
       case( state )
       2'b00:
       begin
            if( inp ) state <= 2'b11;
            else state <= 2'b01;
       end

       2'b01:
       begin
            if( inp ) state <= 2'b10;
            else state <= 2'b11;
