reg		[12:0] outptr;				
wire	empty_rd;					
reg		empty_wr;					


always @(posedge clk)
	if (wr)
		mem[inptr[11:0]] <= data_in;

always @(posedge clk)
	data_out <= mem[outptr[11:0]];


always @(posedge clk)
	if (reset)
		inptr <= 12'd0;
	else if (wr)
		inptr <= inptr + 12'd1;


