always @(posedge clk)
	empty_wr <= empty_rd;

assign empty = empty_rd | empty_wr;




assign full = inptr[12:8]!=outptr[12:8] ? 1'b1 : 1'b0;	

assign last = outptr[7:0] == 8'hFF ? 1'b1 : 1'b0;	

