      din_s1 <= 1'b0;
    else
      din_s1 <= next_din_s1;
  end

  `else 
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) 
      din_s1 <= 1'b0;
    else
      din_s1 <= din;
  end
  `endif

  generate
    if (depth < 3) begin
      always @(posedge clk or negedge reset_n) begin
        if (reset_n == 0) 
          dreg <= {depth-1{1'b0}};            
        else
          dreg <= din_s1;
      end         
    end else begin
      always @(posedge clk or negedge reset_n) begin
        if (reset_n == 0) 
          dreg <= {depth-1{1'b0}};
        else
          dreg <= {dreg[depth-3:0], din_s1};
      end
    end
  endgenerate

  assign dout = dreg[depth-2];

endmodule

