description:
Design a versatile flip-flop module that implements four types of flip-flops: D, JK, T, and SR. The module utilizes control signals such as CLK (clock), CLR (clear), and PR (preset) to manage the state transitions. The D flip-flop stores the input D signal on the rising edge of the clock. The JK flip-flop toggles its output based on the inputs J and K, allowing for versatile counting behavior. The T flip-flop toggles its output when the T input is high, serving as a toggle flip-flop suitable for binary counting. Lastly, the SR flip-flop sets or resets the output based on the S and R inputs. The output Q and its complement Q_not are provided for use in digital circuits. This module is suitable for creating state storage elements in digital systems, enabling a variety of sequential logic designs.
module top_module(
  input D, CLK, CLR, PR,
  output Q, Q_not
);

code:
module top_module(
  input D, CLK, CLR, PR,
  output Q, Q_not
);// D flip-flop inputs and outputs
reg D_FF, Q_FF, Q_not_FF;
always @(posedge CLK, posedge CLR, posedge PR) begin
  if (CLR) begin
    Q_FF <= 0;
    Q_not_FF <= 1;
  end else if (PR) begin
    Q_FF <= 1;
    Q_not_FF <= 0;
  end else begin
    Q_FF <= D_FF;
    Q_not_FF <= ~D_FF;
  end
end
assign Q = Q_FF;
assign Q_not = Q_not_FF;

// JK flip-flop inputs and outputs
reg J_FF, K_FF;
always @(posedge CLK, posedge CLR, posedge PR) begin
  if (CLR) begin
    Q_FF <= 0;
    Q_not_FF <= 1;
  end else if (PR) begin
    Q_FF <= 1;
    Q_not_FF <= 0;
  end else begin
    if (J_FF && K_FF) begin
      Q_FF <= ~Q_FF;
      Q_not_FF <= ~Q_not_FF;
    end else if (J_FF) begin
      Q_FF <= 1;
      Q_not_FF <= 0;
    end else if (K_FF) begin
      Q_FF <= 0;
      Q_not_FF <= 1;
    end
  end
end

// T flip-flop inputs and outputs
reg T_FF;
always @(posedge CLK, posedge CLR, posedge PR) begin
  if (CLR) begin
    Q_FF <= 0;
    Q_not_FF <= 1;
  end else if (PR) begin
    Q_FF <= 1;
    Q_not_FF <= 0;
  end else begin
    if (T_FF) begin
      Q_FF <= ~Q_FF;
      Q_not_FF <= ~Q_not_FF;
    end
  end
end

// SR flip-flop inputs and outputs
reg S_FF, R_FF;
always @(posedge CLK, posedge CLR, posedge PR) begin
  if (CLR) begin
    Q_FF <= 0;
    Q_not_FF <= 1;
  end else if (PR) begin
    Q_FF <= 1;
    Q_not_FF <= 0;
  end else begin
    if (S_FF) begin
      Q_FF <= 1;
      Q_not_FF <= 0;
    end else if (R_FF) begin
      Q_FF <= 0;
      Q_not_FF <= 1;
    end
  end
end

endmodule

