  assign nor1_out[3] = ~(in[6] | in[7]);

  assign nor2_out[0] = ~(nor1_out[0] | nor1_out[1]);
  assign nor2_out[1] = ~(nor1_out[2] | nor1_out[3]);

  assign nor3_out[0] = ~(nor2_out[0] | nor2_out[1]);

  // Assigning output signals
  always @* begin
    out1 = nor3_out[0];
    out2 = ~(nor3_out[0] | nor3_out[1]);
  end

endmodule

