description:
Design a circuit that generates a 1 Hz clock signal from a higher-frequency input clock. The module uses a counter to count clock cycles, toggling the output signal, clk_1Hz, every 50,000 clock cycles. It also includes a reset signal which initializes the counter and the output clock signal to zero when activated.
module top_module(
	input wire clk, reset, 
	output reg clk_1Hz
);

code:
module top_module(
	input wire clk, reset, 
	output reg clk_1Hz
);reg [27:0] counter;

always@(posedge reset or posedge clk)
begin
    if (reset == 1'b1)
        begin
            clk_1Hz <= 0;
            counter <= 0;
        end
    else
        begin
            counter <= counter + 1;
            if ( counter == 50_000)
                begin
                    counter <= 0;
                    clk_1Hz <= ~clk_1Hz;
                end
        end
end
endmodule

